begin;

-- Generated only after the 83/83 authoring hard gate passed.
-- Approved aggregate SHA-256: 88AEAF8623A6B6EE395439BCC103172B99D8795B9C511128363A425B2ABFFB3F
-- This migration changes products.specifications for ACCESSORY rows only.

create or replace function app_private.is_accessory_content_v1(document jsonb)
returns boolean
language plpgsql
immutable
set search_path = pg_catalog
as $function$
declare
  section jsonb;
  item jsonb;
  attribute jsonb;
  section_index integer := 0;
  section_key text;
  section_order integer;
  seen_keys text[] := array[]::text[];
  seen_orders integer[] := array[]::integer[];
begin
  if jsonb_typeof(document) <> 'object'
     or (select count(*) from jsonb_object_keys(document)) <> 2
     or not (document ?& array['schema', 'sections'])
     or document ->> 'schema' <> 'accessory_content_v1'
     or jsonb_typeof(document -> 'sections') <> 'array' then
    return false;
  end if;

  for section in select value from jsonb_array_elements(document -> 'sections') loop
    section_index := section_index + 1;
    if jsonb_typeof(section) <> 'object'
       or (select count(*) from jsonb_object_keys(section)) <> 7
       or not (section ?& array['key', 'type', 'title', 'display_order', 'body', 'items', 'attributes'])
       or jsonb_typeof(section -> 'key') <> 'string'
       or (section ->> 'key') !~ '^[a-z0-9_]+$'
       or jsonb_typeof(section -> 'type') <> 'string'
       or section ->> 'type' not in (
         'TECHNICAL_SPECS', 'FEATURES', 'USAGE_GUIDE', 'CARE_GUIDE',
         'INSTALLATION_GUIDE', 'PACKAGE_CONTENTS', 'WARRANTY',
         'SHIPPING_NOTE', 'SAFETY_NOTE', 'PURCHASE_NOTE', 'OTHER'
       )
       or jsonb_typeof(section -> 'title') <> 'string'
       or btrim(section ->> 'title') = ''
       or jsonb_typeof(section -> 'display_order') <> 'number'
       or (section ->> 'display_order') !~ '^[0-9]+$'
       or (section ->> 'display_order')::integer <> section_index * 10
       or jsonb_typeof(section -> 'body') not in ('null', 'string')
       or (jsonb_typeof(section -> 'body') = 'string' and btrim(section ->> 'body') = '')
       or jsonb_typeof(section -> 'items') <> 'array'
       or jsonb_typeof(section -> 'attributes') <> 'array' then
      return false;
    end if;

    section_key := section ->> 'key';
    section_order := (section ->> 'display_order')::integer;
    if section_key = any(seen_keys) or section_order = any(seen_orders) then
      return false;
    end if;
    seen_keys := array_append(seen_keys, section_key);
    seen_orders := array_append(seen_orders, section_order);

    for item in select value from jsonb_array_elements(section -> 'items') loop
      if jsonb_typeof(item) <> 'string' or btrim(item #>> '{}') = '' then
        return false;
      end if;
    end loop;

    for attribute in select value from jsonb_array_elements(section -> 'attributes') loop
      if jsonb_typeof(attribute) <> 'object'
         or (select count(*) from jsonb_object_keys(attribute)) <> 2
         or not (attribute ?& array['label', 'value'])
         or jsonb_typeof(attribute -> 'label') <> 'string'
         or btrim(attribute ->> 'label') = ''
         or jsonb_typeof(attribute -> 'value') <> 'string'
         or btrim(attribute ->> 'value') = '' then
        return false;
      end if;
    end loop;

    if (section -> 'body') = 'null'::jsonb
       and jsonb_array_length(section -> 'items') = 0
       and jsonb_array_length(section -> 'attributes') = 0 then
      return false;
    end if;
  end loop;

  return true;
exception when others then
  return false;
end;
$function$;

create temporary table accessory_content_v1_payload (
  pid text primary key,
  sku text not null unique,
  sections jsonb not null
) on commit drop;

insert into accessory_content_v1_payload (pid, sku, sections)
values
  ('3DTRUNKMATVF6', '3DTRUNKMATVF6', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Nhựa TPE nguyên sinh cao cấp, không gây mùi hôi khó chịu và an toàn cho sức khỏe"},{"label":"Vách dựng","value":"3-5cm"},{"label":"Công nghệ sản xuất","value":"Công nghệ Nhật Bản"}]},{"key":"features","type":"FEATURES","title":"Tính năng nổi bật","display_order":20,"body":null,"items":["Chất liệu nhựa TPE cao cấp giúp bảo vệ sàn cốp trước sự va đập, trầy xước và hạn chế bụi bẩn.","Vách dựng 3-5cm, sản phẩm ngăn chặn nước và chất lỏng tràn ra khỏi không gian cốp, giữ cho cốp xe luôn khô ráo và sạch sẽ.","Thảm lót cốp có bề mặt dễ lau chùi, giúp dễ dàng vệ sinh và duy trì sự sạch sẽ cho không gian cốp.","Thiết kế thông minh và sử dụng công nghệ Nhật Bản giúp thảm lót ôm sát sàn xe và không xô lệch, đảm bảo độ chính xác đến từng mm cho xe VinFast VF 6.","Sản phẩm có thiết kế tiện lợi, giúp Khách hàng có thể dễ dàng lắp đặt tại nhà nhanh chóng, thuận tiện."],"attributes":[]},{"key":"warranty","type":"WARRANTY","title":"Chính sách bảo hành","display_order":30,"body":null,"items":["Thời hạn bảo hành kéo dài 24 tháng tính từ ngày nhận hàng."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Lưu ý khi mua hàng","display_order":40,"body":null,"items":["Chính sách đổi trả sản phẩm lỗi trong vòng 3 ngày kể từ ngày nhận hàng áp dụng cho Khách hàng mua Online, chỉ áp dụng đối với các lỗi do nhà sản xuất."],"attributes":[]}]$sections$::jsonb),
  ('ACS10000002', 'ACS10000002', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Nhựa nguyên sinh cao cấp, không độc hại"},{"label":"Tấm ghế phụ","value":"719,5252 x 505,1932 mm"},{"label":"Tấm ghế lái","value":"725,3053 x 496,2708 mm"},{"label":"Hai tấm hàng ghế hai","value":"485 x 504,4809 mm mỗi tấm"},{"label":"Tấm giữa hàng ghế hai","value":"309,1855 x 502,4421 mm"}]},{"key":"features","type":"FEATURES","title":"Đặc điểm nổi bật","display_order":20,"body":null,"items":["Chống nước, chống trượt và dễ vệ sinh.","Được may đo cho VinFast Nerio Green và có nút cố định để hạn chế xô lệch."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Lưu ý thông tin sản phẩm","display_order":30,"body":"Các thông tin sản phẩm có thể thay đổi mà không cần báo trước.","items":[],"attributes":[]}]$sections$::jsonb),
  ('ACS10000005', 'ACS10000005', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Nhựa TPE"},{"label":"Phương pháp thiết kế","value":"Quét 3D theo sàn xe"},{"label":"Chứng nhận","value":"QUATEST 3; đáp ứng các tiêu chí RoHS theo dữ liệu nguồn"}]},{"key":"features","type":"FEATURES","title":"Đặc điểm nổi bật","display_order":20,"body":null,"items":["Chống bụi, chống thấm nước và ôm sát sàn xe.","Bề mặt dưới bám sàn, hỗ trợ chống trơn trượt và hạn chế xô lệch.","Không chứa kim loại nặng và không có mùi độc hại theo dữ liệu nguồn.","Có khả năng chống cháy, chống nước và hỗ trợ giảm tiếng ồn động cơ theo dữ liệu nguồn."],"attributes":[]},{"key":"warranty","type":"WARRANTY","title":"Bảo hành","display_order":30,"body":"Bảo hành 24 tháng từ ngày nhận hàng.","items":[],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Đổi trả đơn hàng online","display_order":40,"body":"Sản phẩm lỗi do nhà sản xuất được đổi trả trong 3 ngày từ ngày nhận hàng đối với khách hàng mua online.","items":[],"attributes":[]}]$sections$::jsonb),
