  ('ACS10000038', 'ACS10000038', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Vải lưới đen chống UV, khung thép dẻo"},{"label":"Rèm cửa trước","value":"58 x 36,4 cm"},{"label":"Rèm cửa sau","value":"84 x 37 cm"}]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Bộ sản phẩm","display_order":20,"body":null,"items":["Hai rèm dài cho cửa sau.","Hai rèm ngắn cho cửa trước.","Hai bộ đế nhựa."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý an toàn","display_order":30,"body":null,"items":["Lắp đúng chiều và vị trí.","Không dùng khi kính cửa đang hạ hoặc mở.","Không để rèm che túi khí.","Tránh nguồn nhiệt cao và không để trẻ em nghịch."],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Vệ sinh và bảo quản","display_order":40,"body":null,"items":["Lau bụi định kỳ bằng khăn ẩm; không dùng chất tẩy mạnh.","Gập nhẹ khi tháo, cất trong túi ở nơi khô ráo, tránh nắng trực tiếp và độ ẩm cao."],"attributes":[]}]$sections$::jsonb),
  ('ACS10000039', 'ACS10000039', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông số điện","display_order":10,"body":null,"items":[],"attributes":[{"label":"Giao diện sạc","value":"IEC 62196-2 mức 2, cổng cái, 5 tiếp điểm"},{"label":"Nguồn vào","value":"AC 1 pha, 3 dây, 230 V ± 10%, 50/60 Hz ± 1%"},{"label":"Đầu ra","value":"AC 1 pha, 230 V ± 10%, 50/60 Hz ± 1%, tối đa 2,2 kW"},{"label":"Chân cắm","value":"Loại E/F theo chứng chỉ VDE"},{"label":"Nhiệt độ hoạt động","value":"-25°C đến 45°C"},{"label":"Nhiệt độ lưu trữ","value":"-40°C đến 85°C"},{"label":"Độ ẩm hoạt động","value":"5%–95% RH, không ngưng tụ"},{"label":"Bảo vệ","value":"Dòng rò, quá nhiệt, quá dòng, quá áp và thấp áp; súng sạc IP54"}]},{"key":"usage_guide","type":"USAGE_GUIDE","title":"Trình tự sạc","display_order":20,"body":null,"items":["Cắm phích bộ sạc vào ổ điện E/F và chờ đèn đỏ sáng, đèn vàng cùng đèn xanh tắt.","Cắm súng sạc vào cổng sạc trên xe.","Theo dõi tín hiệu bắt đầu sạc: đèn đỏ sáng, đèn xanh và đèn vàng nháy một lần.","Khi sạc đầy, dùng nút dừng sạc trên cửa xe hoặc màn hình để nhả khóa súng sạc.","Rút súng sạc khỏi xe, sau đó tháo phích cắm khỏi ổ điện."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"An toàn điện","display_order":30,"body":null,"items":["Không sử dụng khi súng sạc, phích cắm, cáp, hộp điều khiển hoặc ổ cắm có dấu hiệu hỏng, gỉ, nứt hay kết nối lỏng.","Chỉ dùng ổ cắm E/F đạt tiêu chuẩn an toàn điện tại Việt Nam và lưới điện có nối đất phù hợp.","Bố trí dây và ổ cắm tránh nơi đông người; không đặt cáp trên vật sắc nhọn."],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Vệ sinh và bảo quản","display_order":40,"body":null,"items":["Lau bằng vải khô, mềm; không nhúng thiết bị vào nước và tránh để đầu súng tiếp xúc với hơi ẩm hoặc chất lỏng.","Không dùng rượu, xăng, axeton hoặc chất tẩy có nguy cơ ăn mòn, cháy nổ."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Khả năng tương thích","display_order":50,"body":"Xe VF 3 cần có bộ chuyển đổi mới sử dụng được bộ sạc này.","items":[],"attributes":[]}]$sections$::jsonb),
