  ('ACS10000142', 'ACS10000142', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Vải lưới đen chống UV, khung thép dẻo"},{"label":"Rèm cửa trước","value":"73 x 42 cm"},{"label":"Rèm cửa sau","value":"34 x 37 cm"}]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Bộ sản phẩm","display_order":20,"body":null,"items":["Hai rèm dài cho cửa sau, có nam châm.","Hai rèm ngắn cho cửa trước.","Hai bộ đế nhựa."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý an toàn","display_order":30,"body":null,"items":["Lắp đúng chiều và vị trí.","Không dùng khi kính cửa đang hạ hoặc mở.","Không để rèm che túi khí.","Tránh nguồn nhiệt cao và không để trẻ em nghịch."],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Vệ sinh và bảo quản","display_order":40,"body":null,"items":["Lau bụi định kỳ bằng khăn ẩm; không dùng chất tẩy mạnh.","Gập nhẹ khi tháo, cất trong túi ở nơi khô ráo, tránh nắng trực tiếp và độ ẩm cao."],"attributes":[]}]$sections$::jsonb),
  ('ACS10000144', 'ACS10000144', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Vải lưới đen chống UV, khung thép dẻo"},{"label":"Rèm cửa trước","value":"58 x 41,6 cm"},{"label":"Rèm cửa sau","value":"93,5 x 42,5 cm"}]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Bộ sản phẩm","display_order":20,"body":null,"items":["Hai rèm dài cho cửa sau.","Hai rèm ngắn cho cửa trước.","Hai bộ đế nhựa."],"attributes":[]},{"key":"installation_guide","type":"INSTALLATION_GUIDE","title":"Lắp đặt","display_order":30,"body":null,"items":["Mở cửa xe, lấy rèm khỏi bao bì và lau sạch bề mặt tapi nhựa bên dưới cửa.","Dán hai đế nhựa tại chân rèm bằng lớp keo hai mặt.","Gắn rèm dài vào cửa sau, căn bốn cạnh rèm theo bốn cạnh cửa và xoay nam châm hướng ra ngoài.","Đặt cạnh dưới rèm vào rãnh hai đế nhựa; phần trên được giữ vào khung cửa bằng nam châm."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý an toàn","display_order":40,"body":null,"items":["Lắp đúng chiều và vị trí.","Không dùng khi kính cửa đang hạ hoặc mở.","Không để rèm che túi khí.","Tránh nguồn nhiệt cao và không để trẻ em nghịch."],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Vệ sinh và bảo quản","display_order":50,"body":null,"items":["Lau bụi định kỳ bằng khăn ẩm; không dùng chất tẩy mạnh.","Gập nhẹ khi tháo, cất trong túi ở nơi khô ráo, tránh nắng trực tiếp và độ ẩm cao."],"attributes":[]}]$sections$::jsonb),
  ('ACS10000145', 'ACS10000145', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Dòng xe","value":"VinFast VF 3"},{"label":"Đời xe","value":"2024–2025"},{"label":"Vị trí","value":"Lưng ghế sau, hàng ghế 2"},{"label":"Chất liệu","value":"Nhựa PP"},{"label":"Màu sắc","value":"Đen"},{"label":"Bề mặt","value":"Nhám mờ, chống trầy và bám bẩn theo dữ liệu nguồn"}]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Bộ sản phẩm","display_order":20,"body":null,"items":["Một tấm ốp nguyên khối.","Bốn pát sắt.","Bốn chốt nhựa.","Hai đai ốc và hai bulông."],"attributes":[]},{"key":"installation_guide","type":"INSTALLATION_GUIDE","title":"Lắp đặt","display_order":30,"body":null,"items":["Vệ sinh bề mặt lưng ghế và kiểm tra đủ linh kiện.","Định vị bốn pát sắt dưới lưng ghế; dùng ốc có sẵn cho hai pát trên và bộ bulông, đai ốc kèm theo cho hai pát dưới.","Căn bốn lỗ tấm ốp với bốn pát sắt rồi nhấn bốn chốt nhựa đúng vị trí.","Kiểm tra các chốt và độ chắc chắn sau khi lắp."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý sử dụng","display_order":40,"body":null,"items":["Giữ tải trọng dưới 50 kg và phân bố đều.","Sắp xếp, cố định hàng hóa chắc chắn.","Kiểm tra thường xuyên và thay thế khi hư hỏng."],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Bảo quản","display_order":50,"body":null,"items":["Vệ sinh định kỳ; không dùng chất tẩy mạnh hoặc vật cứng chà xát.","Tránh đạp hoặc gõ mạnh làm tấm ốp nứt vỡ."],"attributes":[]}]$sections$::jsonb),
  ('ACS10000177', 'ACS10000177', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Dòng xe","value":"VinFast Limo Green"},{"label":"Đời xe","value":"2025"},{"label":"Vị trí","value":"Hàng ghế trước, hàng ghế 2 và hàng ghế 3"},{"label":"Chất liệu","value":"Nhựa TPE"},{"label":"Màu sắc","value":"Đen"}]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Bộ sản phẩm","display_order":20,"body":null,"items":["Một thảm bên lái.","Một thảm bên phụ.","Một thảm hàng ghế 2.","Một thảm hàng ghế 3."],"attributes":[]},{"key":"installation_guide","type":"INSTALLATION_GUIDE","title":"Lắp đặt","display_order":30,"body":null,"items":["Vệ sinh sàn và xác định đúng vị trí từng thảm.","Đặt thảm đúng chiều, bảo đảm các gờ khớp với sàn xe.","Kiểm tra thảm không cản chân ga, chân phanh hoặc hoạt động trượt, gập ghế."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý sử dụng","display_order":40,"body":null,"items":["Tránh vật sắc nhọn hoặc hóa chất tiếp xúc trực tiếp.","Không chèn vật nặng lên vách thảm trong thời gian dài.","Thay thảm khi phát hiện hư hỏng."],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Vệ sinh và bảo quản","display_order":50,"body":null,"items":["Lau nhanh bằng khăn ẩm hoặc chổi mềm.","Tháo thảm và xịt nước áp lực vừa phải khi vệ sinh kỹ; có thể dùng dung dịch cho nhựa TPE.","Lau khô hoặc phơi nơi thoáng, tránh nắng gắt kéo dài.","Không cắt, khoan hoặc thay đổi cấu trúc thảm."],"attributes":[]}]$sections$::jsonb),
  ('ACS10000178', 'ACS10000178', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Dòng xe","value":"VinFast Limo Green"},{"label":"Đời xe","value":"2025"},{"label":"Vị trí","value":"Cốp sau"},{"label":"Chất liệu","value":"Nhựa TPE"},{"label":"Màu sắc","value":"Đen"}]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Bộ sản phẩm","display_order":20,"body":"Một thảm lót cốp.","items":[],"attributes":[]},{"key":"installation_guide","type":"INSTALLATION_GUIDE","title":"Lắp đặt","display_order":30,"body":null,"items":["Vệ sinh sạch bề mặt sàn và xác định đúng vị trí thảm.","Đặt thảm đúng chiều, bảo đảm các gờ khớp với cốp xe.","Kiểm tra để thảm không cản trở việc đóng mở cốp hoặc gập dựng ghế sau."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý sử dụng","display_order":40,"body":null,"items":["Tránh để vật sắc nhọn hoặc hóa chất tiếp xúc trực tiếp với thảm.","Không chèn vật nặng lên vách thảm trong thời gian dài.","Thay thảm khi phát hiện hư hỏng."],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Vệ sinh và bảo quản","display_order":50,"body":null,"items":["Lau nhanh bằng khăn ẩm hoặc chổi mềm.","Khi vệ sinh kỹ, tháo thảm và xịt nước với áp lực vừa phải; có thể dùng dung dịch chuyên dụng cho nhựa TPE.","Lau khô hoặc phơi nơi thoáng mát, tránh nắng gắt kéo dài.","Không cắt, khoan hoặc thay đổi cấu trúc thảm."],"attributes":[]}]$sections$::jsonb),
  ('ACS10000179', 'ACS10000179', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Dòng xe","value":"VinFast VF 3"},{"label":"Đời xe","value":"2024–2025"},{"label":"Vị trí","value":"Cốp sau"},{"label":"Chất liệu","value":"Nhựa TPE"},{"label":"Màu sắc","value":"Đen"}]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Bộ sản phẩm","display_order":20,"body":"Một thảm lót cốp.","items":[],"attributes":[]},{"key":"installation_guide","type":"INSTALLATION_GUIDE","title":"Lắp đặt","display_order":30,"body":null,"items":["Vệ sinh sàn và xác định vị trí thảm.","Đặt thảm đúng chiều, bảo đảm các gờ khớp với cốp xe.","Kiểm tra để thảm không cản trở việc đóng mở cốp hoặc gập dựng ghế sau."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý sử dụng","display_order":40,"body":null,"items":["Tránh vật sắc nhọn hoặc hóa chất tiếp xúc trực tiếp.","Không chèn vật nặng lên vách thảm trong thời gian dài.","Thay thảm khi phát hiện hư hỏng."],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Vệ sinh và bảo quản","display_order":50,"body":null,"items":["Lau nhanh bằng khăn ẩm hoặc chổi mềm.","Tháo thảm và xịt nước áp lực vừa phải khi vệ sinh kỹ; có thể dùng dung dịch cho nhựa TPE.","Lau khô hoặc phơi nơi thoáng, tránh nắng gắt kéo dài.","Không cắt, khoan hoặc thay đổi cấu trúc thảm."],"attributes":[]}]$sections$::jsonb),
  ('ACS20000012', 'ACS20000012', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Màu sắc","value":"Đen"},{"label":"Bộ nan","value":"10 múi"},{"label":"Bán kính nan","value":"58,5 cm"},{"label":"Đường kính khi bung","value":"103 cm"},{"label":"Cơ chế mở","value":"Nút bấm tự động hai chiều"}]},{"key":"features","type":"FEATURES","title":"Đặc điểm nổi bật","display_order":20,"body":null,"items":["Nan thép sơn tĩnh điện, xi mạ hai lớp và kết hợp sợi carbon để hạn chế rỉ sét, ố vàng.","Lớp Pongee tráng keo đen ở mặt trong hỗ trợ chống nắng và tia UV.","Bao ô hai lớp vải có khóa kéo và nút bấm."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Lưu ý thông tin sản phẩm","display_order":30,"body":"Các thông tin sản phẩm có thể thay đổi mà không cần báo trước.","items":[],"attributes":[]}]$sections$::jsonb),
  ('ACS20000013', 'ACS20000013', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Vải","value":"Pongee tráng keo đen mặt trong"},{"label":"Nan kèo","value":"Thép sơn tĩnh điện kết hợp carbon fiber"},{"label":"Kết cấu","value":"16 múi, gồm 8 múi tầng trên và 8 múi tầng dưới"},{"label":"Bán kính nan","value":"R41 cm và R79 cm theo dữ liệu nguồn"},{"label":"Bán kính bung","value":"136 cm"},{"label":"Cơ chế mở","value":"Nút bấm mở tự động"}]},{"key":"features","type":"FEATURES","title":"Đặc điểm nổi bật","display_order":20,"body":null,"items":["Kết cấu hai tầng hỗ trợ chống gió lật.","Lớp Pongee tráng keo đen mặt trong có khả năng chống thấm nước và chống bức xạ tia UV.","Tay cầm nhẹ, êm và hỗ trợ cân bằng khi sử dụng trong thời tiết mưa."],"attributes":[]}]$sections$::jsonb),
  ('ACS30000028', 'ACS30000028', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin sản phẩm","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"100% kaki nhập khẩu"},{"label":"Màu sắc","value":"Đen"},{"label":"Kiểu dáng","value":"Unisex, freesize"},{"label":"Chu vi vòng đầu","value":"55–60 cm"},{"label":"Điều chỉnh","value":"Khóa phía sau mũ"}]},{"key":"features","type":"FEATURES","title":"Đặc điểm nổi bật","display_order":20,"body":null,"items":["Chất vải dày dặn, thoáng mát.","Form mũ chắc chắn, đứng dáng và tạo cảm giác vừa vặn khi đội."],"attributes":[]}]$sections$::jsonb),
  ('ACS30000078', 'ACS30000078', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Số lượng","value":"6 miếng"},{"label":"Chất liệu","value":"HDF và lá vàng"},{"label":"Kích thước mỗi miếng","value":"10 x 10 cm"},{"label":"Hoàn thiện","value":"Sơn mài 20 lớp, phủ vàng và phủ bóng"}]},{"key":"features","type":"FEATURES","title":"Đặc điểm nổi bật","display_order":20,"body":"Bộ lót cốc được chế tác bởi nghệ nhân truyền thống và gợi nhắc các cột mốc của VinFast.","items":[],"attributes":[]}]$sections$::jsonb),
  ('ACS30000104', 'ACS30000104', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin sản phẩm","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Vải kaki cotton"},{"label":"Kiểu dáng","value":"Form cứng, sáu múi, unisex, freesize"},{"label":"Khóa","value":"Khóa gập inox phía sau"},{"label":"Logo","value":"Ép nhiệt nhựa cứng bóng màu vàng kim loại"},{"label":"Xuất xứ","value":"Sản xuất tại Việt Nam"}]},{"key":"features","type":"FEATURES","title":"Đặc điểm nổi bật","display_order":20,"body":null,"attributes":[],"items":["Hai múi trước ép mex giúp giữ form.","Đai đệm phía trong tạo cảm giác êm khi đội.","Freesize, điều chỉnh độ rộng bằng khóa sau mũ."]}]$sections$::jsonb),
  ('ACS30000141', 'ACS30000141', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Kích thước","value":"205x78x35cm."},{"label":"Sức tải","value":"75kg."},{"label":"Cân nặng","value":"22kg"},{"label":"Màu sắc","value":"Đen"},{"label":"Chất liệu","value":"ABS + PMMA, vật liệu kết hợp giữa khả năng chịu lực, chống va đập của ABS và bề mặt bóng mịn, chống trầy xước của PMMA, đảm bảo độ bền vượt trội, khả năng chống chịu thời tiết và tính thẩm mỹ cao."}]},{"key":"features","type":"FEATURES","title":"Tính năng nổi bật","display_order":20,"body":null,"items":["Cách lắp đặt linh hoạt: Hệ thống mở hai bên tiện lợi cùng kẹp hình chữ U chắc chắn, giúp việc lắp đặt và sử dụng trở nên dễ dàng hơn bao giờ hết.","Thiết kế khí động học tiên tiến: Với thiết kế dạng cánh có phần mui nghiêng thoải về trước, cốp nóc ô tô VinFast VF 8 giúp giảm lực cản của gió, từ đó giúp xe có thể đi nhanh hơn, tiết kiệm nhiên liệu mà không gây ra tiếng ồn, rung lắc khi di chuyển.","Dung tích chứa đồ lớn: Với dung tích lên tới 450 lít, cốp nóc ô tô VinFast VF 8 cho phép người dùng có thể thoải mái chứa được nhiều loại đồ đạc khác nhau như như vali, túi xách, đồ dùng thể thao, dụng cụ cắm trại… vô cùng phù hợp với những chuyến đi dài.","Hoàn thiện tinh tế: Phần nắp được xử lý bề mặt bóng loáng tạo cảm giác sang trọng; trong khi phần đáy có kết cấu hạt, tăng độ bền và chống trượt.","Màu sắc hiện đại: Tông màu đen chủ đạo phù hợp với thiết kế thăng hạng đẳng cấp của VinFast VF 8.","Cốp nóc ô tô VinFast VF 8 không chỉ là phụ kiện thiết yếu, mà còn là biểu tượng của sự tiện nghi và đẳng cấp. Phù hợp với mọi hành trình, từ chuyến đi ngắn ngày đến những chuyến phiêu lưu dài hơi."],"attributes":[]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Thành phần đóng gói","display_order":30,"body":null,"items":["Đóng gói an toàn: Sản phẩm được bảo vệ bằng lớp phim bảo vệ, túi bóng khí và giấy Kraft, đảm bảo không bị trầy xước hay hư hỏng trong quá trình vận chuyển."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý an toàn","display_order":40,"body":null,"items":["Độ an toàn và bảo mật cao: Với hệ thống khóa tích hợp sẵn trên 2 bên của cốp nóc ô tô, người dùng hoàn toàn có thể an tâm về độ an toàn tuyệt đối của các đồ đạc, hành lý của mình. (*) Lưu ý: Vui lòng khóa bên còn lại trước khi mở."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Lưu ý khi mua hàng","display_order":50,"body":null,"items":["*Ghi chú: cần mua cùng thanh ngang giá nóc, thanh dọc giá nóc để có thể lắp lên xe."],"attributes":[]}]$sections$::jsonb),
  ('ACS30000142', 'ACS30000142', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Thương hiệu","value":"Thule"},{"label":"Chiều rộng tải","value":"100-110cm."},{"label":"Chiều dài","value":"95cm."},{"label":"Sức tải / Tải trọng tối đa","value":"75kg"},{"label":"Cân nặng","value":"21.3kg"},{"label":"Màu sắc","value":"Đen"},{"label":"Chất liệu","value":"Aluminium (Nhôm)"}]},{"key":"features","type":"FEATURES","title":"Tính năng nổi bật","display_order":20,"body":null,"items":["Sản phẩm thiết kế dành riêng cho dòng xe VinFast VF 8.","Giao diện QuickAccess: Cho phép lắp đặt và tháo gỡ dễ dàng nhờ rãnh chữ T.","Công nghệ Wind Diffuser: Tích hợp trên các thanh ngang WingBar Edge, làm xáo trộn luồng không khí để giảm tiếng ồn của gió và lực cản khí động học, từ đó giúp cải thiện khả năng tiết kiệm nhiên liệu khi xe di chuyển.","Thiết kế RailEdge: Giảm lực cản khí động học bằng cách cho phép không khí tách ra khỏi thanh, hỗ trợ xe vận hành mượt mà hơn.","Phím giới hạn mô-men xoắn: Cung cấp chỉ báo khi giá đỡ đã được cố định an toàn và đúng cách vào xe, giúp người dùng yên tâm về độ an toàn khi lắp đặt.","Khóa an toàn Thule: Thanh ngang được cố định bằng một ổ khóa thông minh Thule đi kèm, tăng cường bảo vệ đồ đạc khỏi các rủi ro thất thoát."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Lưu ý khi mua hàng","display_order":30,"body":null,"items":["*Ghi chú: cần mua cùng thanh dọc giá nóc và cốp phi thuyền để có thể có trọn bộ sản phẩm."],"attributes":[]}]$sections$::jsonb),
  ('ACS40000013', 'ACS40000013', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin sản phẩm","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Vải dù tráng PVC nhẹ, vân tổ ong"},{"label":"Kiểu dáng","value":"Cánh dơi một mũ, có kính đèn xe và lỗ xỏ gương"},{"label":"Màu sắc","value":"Xanh biển"},{"label":"Kích thước","value":"138 x 151 cm tính cả mũ, sai số ±2 cm"}]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Bộ sản phẩm","display_order":20,"body":"Áo mưa và túi đựng cùng chất liệu.","items":[],"attributes":[]},{"key":"usage_guide","type":"USAGE_GUIDE","title":"Cách sử dụng","display_order":30,"body":null,"items":["Trùm áo kín người, tay lái và yên xe.","Kéo dây rút hoặc bo mũ để hạn chế gió lật.","Chỉnh áo không che đèn, gương hoặc tầm nhìn."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý an toàn","display_order":40,"body":"Bảo đảm áo không bị cuốn vào bánh xe hoặc xích xe.","items":[],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Bảo quản","display_order":50,"body":null,"items":["Treo áo cho ráo nước và lau sạch trước khi gấp.","Cất ở nơi thoáng mát, tránh nắng gắt và nhiệt độ cao."],"attributes":[]}]$sections$::jsonb),
  ('ACS40000014', 'ACS40000014', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin sản phẩm","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Vải dù tráng PVC nhẹ, vân tổ ong"},{"label":"Kiểu dáng","value":"Cánh dơi hai mũ, có kính đèn xe và lỗ xỏ gương"},{"label":"Màu sắc","value":"Xanh biển"},{"label":"Kích thước","value":"140 x 152 cm tính cả mũ, sai số ±2 cm"}]},{"key":"package_contents","type":"PACKAGE_CONTENTS","title":"Bộ sản phẩm","display_order":20,"body":"Áo mưa và túi đựng cùng chất liệu.","items":[],"attributes":[]},{"key":"usage_guide","type":"USAGE_GUIDE","title":"Cách sử dụng","display_order":30,"body":null,"items":["Trùm áo kín người, tay lái và yên xe.","Kéo dây rút hoặc bo mũ để hạn chế gió lật.","Chỉnh áo không che đèn, gương hoặc tầm nhìn."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý an toàn","display_order":40,"body":"Bảo đảm áo không bị cuốn vào bánh xe hoặc xích xe.","items":[],"attributes":[]},{"key":"care_guide","type":"CARE_GUIDE","title":"Bảo quản","display_order":50,"body":null,"items":["Treo áo cho ráo nước và lau sạch trước khi gấp.","Cất ở nơi thoáng mát, tránh nắng gắt và nhiệt độ cao."],"attributes":[]}]$sections$::jsonb),
  ('BIN69052209AA', 'BIN69052209AA', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Nhựa TPE có khả năng chống cháy, chống nước cao, không có chất kim loại nặng, không mùi độc hại"},{"label":"Dây chuyền sản xuất","value":"Công nghệ Nhật Bản hiện đại, sản xuất chính hãng tại Việt Nam"},{"label":"Tiêu chuẩn & Chứng nhận","value":"QUATEST 3 (Trung tâm Kỹ thuật Tiêu chuẩn Đo lường Chất lượng 3) & Tiêu chí RoHS"}]},{"key":"features","type":"FEATURES","title":"Tính năng nổi bật","display_order":20,"body":null,"items":["Thảm chống bụi bẩn, chống thấm nước, ôm sát sàn xe, đảm bảo vừa vặn với kích thước sàn tuyệt đối.","Sử dụng công nghệ Nhật Bản, đảm bảo độ chính xác đến từng mm cho xe VinFast VF 3.","Thiết kế thông minh, đảm bảo khả năng giữ bụi tối đa.","Chống trơn trượt, bề mặt dưới bám dính vào sàn xe đảm bảo không xô lệch.","Dễ dàng lắp đặt, dễ dàng vệ sinh."],"attributes":[]}]$sections$::jsonb),
  ('CHG00009020', 'CHG00009020', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông số điện","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chế độ","value":"Sạc có dây AC mức 2"},{"label":"Nguồn vào","value":"1 pha, 230 VAC ± 10%, 50/60 Hz"},{"label":"Đầu ra","value":"230 VAC ± 10%, 50/60 Hz, một cổng"},{"label":"Công suất","value":"7,4 kW"},{"label":"Bảo vệ","value":"Quá áp, thấp áp, dòng rò, quá nhiệt, mất nối đất và chống cháy UL94-V1"}]},{"key":"installation_guide","type":"INSTALLATION_GUIDE","title":"Yêu cầu lắp đặt","display_order":20,"body":null,"items":["Đọc hướng dẫn lắp đặt và tuân thủ quy tắc an toàn.","Dùng dây dẫn theo TCVN 5935-1/IEC 60502-1.","Nguồn vào yêu cầu 230 V, 40 A; MCB 40 A kết hợp RCD type A 30 mA hoặc RCBO 30 mA, dòng 40 A.","Kiểm tra hệ thống nối đất của công trình."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"An toàn và bảo quản","display_order":30,"body":null,"items":["Không ngâm bộ sạc trong nước; không kéo, gập, thắt hoặc dẫm lên cáp.","Không làm rơi bộ điều khiển, đặt vật nặng lên thiết bị hoặc để gần nguồn nhiệt và nắng trực tiếp.","Không sử dụng ngoài phạm vi nhiệt độ -40°C đến 60°C; đậy nắp chống bụi khi không dùng."],"attributes":[]},{"key":"warranty","type":"WARRANTY","title":"Bảo hành","display_order":40,"body":"Bảo hành tại nơi lắp đặt lên đến 24 tháng theo thông tin nguồn.","items":[],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Khả năng tương thích","display_order":50,"body":"Xe VF 3 cần có bộ chuyển đổi mới sử dụng được bộ sạc này.","items":[],"attributes":[]}]$sections$::jsonb),
  ('CHS69060008AB', 'CHS69060008AB', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chất liệu","value":"Nhựa cao cấp, bền bỉ với thời gian."},{"label":"Màu sắc","value":"Đen phối bạc."},{"label":"Tiêu chuẩn","value":"Thiết kế và đánh giá theo tiêu chuẩn của VinFast."}]},{"key":"features","type":"FEATURES","title":"Tính năng nổi bật","display_order":20,"body":null,"items":["Bảo vệ mâm xe khỏi trầy xước, va đập, dễ dàng vệ sinh.","Tăng tính thẩm mỹ, giúp xe trông hiện đại và thể thao hơn, đồng thời bảo vệ mâm xe khỏi hư hại."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Lưu ý khi mua hàng","display_order":30,"body":null,"items":["Giá bán niêm yết là giá của 01 sản phẩm, Khách hàng cần đặt hàng 04 sản phẩm cho 01 xe."],"attributes":[]}]$sections$::jsonb),
  ('CLASSICBOTTLE750ML', 'CLASSICBOTTLE750ML', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Dung tích","value":"750 ml"},{"label":"Trọng lượng","value":"385 g"},{"label":"Chiều cao không nắp","value":"23,5 cm"},{"label":"Chiều cao có nắp","value":"25,4 cm"},{"label":"Đường kính","value":"7,6 cm"},{"label":"Vật liệu","value":"Thép không gỉ 18/8, không chứa BPA"},{"label":"Khả năng giữ nhiệt","value":"Giữ lạnh đến 24 giờ; giữ nóng đến 12 giờ"}]},{"key":"usage_guide","type":"USAGE_GUIDE","title":"Hướng dẫn sử dụng","display_order":20,"body":null,"items":["Dùng để giữ lạnh hoặc giữ nóng; bình có thể chứa nước có gas.","Vặn nắp kín và đúng vị trí.","Đặt bình thẳng đứng khi mở nắp."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý an toàn","display_order":30,"body":null,"items":["Tránh va đập mạnh.","Không dùng trong lò vi sóng, máy rửa chén hoặc ngăn đông.","Không nghiêng bình khi mở nắp để tránh nước nóng đổ ra gây bỏng."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Đổi sản phẩm lỗi","display_order":40,"body":"Đổi một sản phẩm tương ứng trong 3 ngày từ ngày nhận hàng đối với lỗi do sản xuất.","items":[],"attributes":[]}]$sections$::jsonb),
  ('EEP30000011', 'EEP30000011', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông số điện","display_order":10,"body":null,"items":[],"attributes":[{"label":"Chế độ","value":"Sạc có dây AC mức 2"},{"label":"Nguồn vào","value":"3 pha, 400 VAC ± 10%, 50/60 Hz"},{"label":"Đầu ra","value":"400 VAC ± 10%, 50/60 Hz, một cổng"},{"label":"Công suất tối đa","value":"11 kW"},{"label":"Bảo vệ","value":"Quá áp, thấp áp, dòng rò, quá tải, quá nhiệt và mất nối đất"}]},{"key":"installation_guide","type":"INSTALLATION_GUIDE","title":"Yêu cầu lắp đặt","display_order":20,"body":"Đọc kỹ hướng dẫn lắp đặt, tuân thủ quy tắc an toàn và liên hệ CSKH VinFast nếu bộ sạc có dấu hiệu bất thường hoặc không hoạt động.","items":[],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"An toàn và bảo quản","display_order":30,"body":null,"items":["Không ngâm bộ sạc trong nước; không kéo, gập, thắt hoặc dẫm lên cáp.","Không làm rơi bộ điều khiển, đặt vật nặng lên thiết bị hoặc để gần nguồn nhiệt và nắng trực tiếp.","Không sử dụng ngoài phạm vi nhiệt độ -40°C đến 60°C.","Khi không sử dụng, cuộn cáp hoặc đặt lên giá đỡ và cắm đầu nối vào vị trí bảo quản được chỉ định."],"attributes":[]},{"key":"warranty","type":"WARRANTY","title":"Bảo hành","display_order":40,"body":"Bảo hành tại nơi lắp đặt lên đến 24 tháng theo thông tin nguồn.","items":[],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Khả năng tương thích","display_order":50,"body":"Xe VF 3 cần có bộ chuyển đổi mới sử dụng được bộ sạc này.","items":[],"attributes":[]}]$sections$::jsonb),
  ('EEP31001000', 'EEP31001000', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Kích thước & trọng lượng","value":"VF 8: 2290,7 x1516,6x7,4mm | 34,5 ± 3 kg."},{"label":"Độ dày","value":"1,0mm."},{"label":"Vật liệu, màu sắc","value":"Theo sơn đen nhám."}]},{"key":"features","type":"FEATURES","title":"Tính năng nổi bật","display_order":20,"body":null,"items":["Chịu va đập cao: Độ bền cao, bảo vệ pin khỏi các tác động cực đoan từ bên ngoài.","Chống chịu môi trường: Chống chịu nhiệt độ độ ẩm cao, chống ăn mòn từ muối, ẩm và hóa chất như dầu mỡ, độ bền lớp sơn chống chịu môi trường muối khắc nghiệt.","Không ảnh hưởng đến rung, ồn: Đảm bảo xe vận hành êm ái, không làm gia tăng độ rung hay tiếng ồn.","Dễ vệ sinh: Thiết kế bề mặt có lỗ thoát nước giúp dễ dàng lau chùi, chống bám bẩn.","Kiểm định chất lượng: Được VinFast kiểm định về chất lượng an toàn bảo vệ pin và không ảnh hưởng tới tính năng của xe."],"attributes":[]},{"key":"warranty","type":"WARRANTY","title":"Chính sách bảo hành","display_order":30,"body":null,"items":["Chính sách bảo hành: Không ảnh hưởng đến chính sách bảo hành của gói pin nếu được lắp đặt tại các đơn vị ủy quyền VinFast."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Lưu ý khi mua hàng","display_order":40,"body":null,"items":["Phiên bản áp dụng: VF 8 sử dụng pin VinES (SDI cell).","Lưu ý: Giá sản phẩm đã bao gồm VAT, chưa bao gồm chi phí lắp đặt."],"attributes":[]}]$sections$::jsonb),
