  ('NERIOGREENBATTERYCOVER', 'NERIOGREENBATTERYCOVER', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Kích thước & trọng lượng","value":"Nerio Green_LFP: 1737 x1361x5mm | 22,7 ± 1 kg."},{"label":"Độ dày","value":"1,0mm."},{"label":"Vật liệu, màu sắc","value":"Theo sơn đen nhám."}]},{"key":"features","type":"FEATURES","title":"Tính năng nổi bật","display_order":20,"body":null,"items":["Chịu va đập cao: Độ bền cao, bảo vệ pin khỏi các tác động cực đoan từ bên ngoài.","Chống chịu môi trường: Chống chịu nhiệt độ độ ẩm cao, chống ăn mòn từ muối, ẩm và hóa chất như dầu mỡ, độ bền lớp sơn chống chịu môi trường muối khắc nghiệt.","Không ảnh hưởng đến rung, ồn: Đảm bảo xe vận hành êm ái, không làm gia tăng độ rung hay tiếng ồn.","Dễ vệ sinh: Thiết kế bề mặt có lỗ thoát nước giúp dễ dàng lau chùi, chống bám bẩn.","Kiểm định chất lượng: Được VinFast kiểm định về chất lượng an toàn bảo vệ pin và không ảnh hưởng tới tính năng của xe."],"attributes":[]},{"key":"warranty","type":"WARRANTY","title":"Chính sách bảo hành","display_order":30,"body":null,"items":["Chính sách bảo hành: Không ảnh hưởng đến chính sách bảo hành của gói pin nếu được lắp đặt tại các đơn vị ủy quyền VinFast."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Lưu ý khi mua hàng","display_order":40,"body":null,"items":["Lưu ý: Giá sản phẩm đã bao gồm VAT, chưa bao gồm chi phí lắp đặt."],"attributes":[]}]$sections$::jsonb),
  ('REGISTRATIONLEATHERCASE', 'REGISTRATIONLEATHERCASE', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin sản phẩm","display_order":10,"body":null,"items":[],"attributes":[{"label":"Kích thước","value":"18 x 12 cm (dài x rộng)"},{"label":"Chất liệu","value":"Da Microfiber"},{"label":"Khóa","value":"Khóa bấm từ"},{"label":"Số ngăn","value":"3 ngăn, gồm 2 ngăn nhỏ và 1 ngăn lớn"}]},{"key":"features","type":"FEATURES","title":"Đặc điểm nổi bật","display_order":20,"body":null,"items":["Thiết kế nhiều ngăn giúp phân loại và cất giữ giấy tờ.","Đường may bao quanh chắc chắn, sắc nét."],"attributes":[]}]$sections$::jsonb),
  ('THERMOSCUP470ML', 'THERMOSCUP470ML', $sections$[{"key":"technical_specs","type":"TECHNICAL_SPECS","title":"Thông tin kỹ thuật","display_order":10,"body":null,"items":[],"attributes":[{"label":"Dung tích","value":"470 ml"},{"label":"Chiều cao","value":"12,7 cm"},{"label":"Đường kính","value":"8,6 cm"},{"label":"Chất liệu","value":"Thép không gỉ 18/8"},{"label":"Cấu trúc","value":"Vách kép inox, chân không và lớp đồng"},{"label":"Khả năng giữ nhiệt theo nguồn","value":"Nóng đến 6 giờ, lạnh đến 18 giờ"}]},{"key":"features","type":"FEATURES","title":"Đặc điểm nổi bật","display_order":20,"body":null,"items":["Nắp Tritan hỗ trợ chống rơi vỡ; tay cầm nhẹ và bền.","Công nghệ vách kép hạn chế ngưng tụ nước bên ngoài; miệng rộng giúp vệ sinh dễ hơn.","Đáy silicone hỗ trợ chống trượt và hạn chế tiếng ồn khi đặt lên bàn.","Không chứa BPA và vật liệu được nguồn công bố đạt chuẩn FDA Hoa Kỳ."],"attributes":[]},{"key":"usage_guide","type":"USAGE_GUIDE","title":"Hướng dẫn sử dụng","display_order":30,"body":null,"items":["Dùng để giữ nóng, giữ lạnh hoặc chứa nước có gas; gài nắp đúng vị trí trước khi sử dụng.","Đặt cốc đứng khi mở nắp và thận trọng với đồ uống nóng."],"attributes":[]},{"key":"safety_note","type":"SAFETY_NOTE","title":"Lưu ý an toàn","display_order":40,"body":null,"items":["Tránh va đập mạnh.","Không dùng trong lò vi sóng, máy rửa chén hoặc đặt trực tiếp trong ngăn đông.","Không nghiêng cốc khi mở nắp để tránh nước đổ gây bỏng."],"attributes":[]},{"key":"purchase_note","type":"PURCHASE_NOTE","title":"Đổi trả","display_order":50,"body":"Lỗi do sản xuất được đổi một sản phẩm tương ứng trong 3 ngày từ ngày nhận hàng.","items":[],"attributes":[]}]$sections$::jsonb),
