do $preflight$
declare
  accessory_count integer;
  matched_count integer;
  assignment_count integer;
begin
  if to_regclass('public.catalog_service_labels') is null
     or to_regclass('public.product_service_label_assignments') is null then
    raise exception using
      errcode = '42P01',
      message = 'Apply 013_accessory_service_labels before accessory content v1.';
  end if;

  if exists (
    select 1 from pg_constraint
     where conrelid = 'public.products'::regclass
       and conname = 'products_accessory_content_v1_check'
  ) then
    raise exception using
      errcode = '42710',
      message = 'products_accessory_content_v1_check already exists; audit migration state.';
  end if;

  if (select count(*) from public.products) <> 110 then
    raise exception using
      errcode = '23514',
      message = 'Expected the audited 110-product catalog before content cutover.';
  end if;

  select count(*) into accessory_count
    from public.products
   where product_type = 'ACCESSORY';
  if accessory_count <> 83 or (select count(*) from accessory_content_v1_payload) <> 83 then
    raise exception using
      errcode = '23514',
      message = format('Expected 83 ACCESSORY and 83 payload rows; found %s and %s.', accessory_count, (select count(*) from accessory_content_v1_payload));
  end if;

  if exists (
    select 1 from accessory_content_v1_payload payload
     where not app_private.is_accessory_content_v1(
       jsonb_build_object('schema', 'accessory_content_v1', 'sections', payload.sections)
     )
  ) then
    raise exception using
      errcode = '22023',
      message = 'Generated payload contains an invalid accessory_content_v1 document.';
  end if;

  select count(*) into matched_count
    from public.products product
    join accessory_content_v1_payload payload
      on payload.pid = product.specifications ->> 'pid'
     and payload.sku = product.specifications ->> 'sku'
   where product.product_type = 'ACCESSORY';
  if matched_count <> 83 then
    raise exception using
      errcode = '23514',
      message = format('Expected 83 exact legacy PID/SKU matches, found %s.', matched_count);
  end if;

  if exists (
    select 1
      from public.products product
     where product.product_type = 'ACCESSORY'
       and (
         jsonb_typeof(product.specifications) <> 'object'
         or product.specifications ->> 'pid' is null
         or product.specifications ->> 'sku' is null
       )
  ) then
    raise exception using
      errcode = '22023',
      message = 'Every ACCESSORY must still have legacy PID/SKU before cutover.';
  end if;

  select count(*) into assignment_count
    from public.product_service_label_assignments;
  if assignment_count <> 32
     or (select count(*) from public.product_service_label_assignments assignment join public.catalog_service_labels label on label.id = assignment.service_label_id where label.code = 'installation') <> 7
     or (select count(*) from public.product_service_label_assignments assignment join public.catalog_service_labels label on label.id = assignment.service_label_id where label.code = 'showroom_pickup') <> 25 then
    raise exception using
      errcode = '23514',
      message = 'Normalized service-label verifier must be 32 total / 7 installation / 25 showroom pickup before legacy JSON removal.';
  end if;
end;
$preflight$;

create temporary table accessory_content_v1_guard on commit drop as
select
  (select count(*) from public.products) as product_count,
  (select count(*) from public.product_variants) as variant_count,
  (select count(*) from public.product_media) as media_count,
  (select count(*) from public.inventory_items) as inventory_count,
  (select count(*) from public.product_option_groups) as option_group_count,
  (select count(*) from public.product_option_values) as option_value_count,
  (select count(*) from public.catalog_collections) as collection_count,
  (select count(*) from public.product_collection_memberships) as membership_count,
  (select md5(coalesce(jsonb_agg(jsonb_build_array(id, specifications) order by id)::text, '[]')) from public.products where product_type <> 'ACCESSORY') as non_accessory_spec_checksum,
  (select md5(coalesce(jsonb_agg(jsonb_build_array(id, description) order by id)::text, '[]')) from public.products where product_type = 'ACCESSORY') as accessory_description_checksum;

do $update$
declare
  updated_count integer;
begin
  update public.products product
     set specifications = jsonb_build_object(
       'schema', 'accessory_content_v1',
       'sections', payload.sections
     )
    from accessory_content_v1_payload payload
   where product.product_type = 'ACCESSORY'
     and payload.pid = product.specifications ->> 'pid'
     and payload.sku = product.specifications ->> 'sku';

  get diagnostics updated_count = row_count;
  if updated_count <> 83 then
    raise exception using
      errcode = '23514',
      message = format('Expected to update 83 ACCESSORY rows, updated %s.', updated_count);
  end if;
end;
$update$;

alter table public.products
  add constraint products_accessory_content_v1_check
  check (
    product_type is distinct from 'ACCESSORY'
    or app_private.is_accessory_content_v1(specifications)
  ) not valid;

alter table public.products
  validate constraint products_accessory_content_v1_check;

do $verify$
declare
  guard accessory_content_v1_guard%rowtype;
begin
  select * into strict guard from accessory_content_v1_guard;

  if (select count(*) from public.products where product_type = 'ACCESSORY') <> 83
     or exists (
       select 1 from public.products
        where product_type = 'ACCESSORY'
          and not app_private.is_accessory_content_v1(specifications)
     )
     or exists (
       select 1 from public.products
        where product_type = 'ACCESSORY'
          and specifications ?| array[
            'service_labels', 'images', 'variants', 'price', 'formatted_price',
            'in_stock', 'compatible_models', 'pid', 'sku', 'policy_notes',
            'specification_text', 'specifications'
          ]
     ) then
    raise exception using
      errcode = '23514',
      message = 'ACCESSORY content v1 shape or legacy-key verifier failed.';
  end if;

  if guard.product_count <> (select count(*) from public.products)
     or guard.variant_count <> (select count(*) from public.product_variants)
     or guard.media_count <> (select count(*) from public.product_media)
     or guard.inventory_count <> (select count(*) from public.inventory_items)
     or guard.option_group_count <> (select count(*) from public.product_option_groups)
     or guard.option_value_count <> (select count(*) from public.product_option_values)
     or guard.collection_count <> (select count(*) from public.catalog_collections)
     or guard.membership_count <> (select count(*) from public.product_collection_memberships)
     or guard.non_accessory_spec_checksum is distinct from (
       select md5(coalesce(jsonb_agg(jsonb_build_array(id, specifications) order by id)::text, '[]'))
         from public.products where product_type <> 'ACCESSORY'
     )
     or guard.accessory_description_checksum is distinct from (
       select md5(coalesce(jsonb_agg(jsonb_build_array(id, description) order by id)::text, '[]'))
         from public.products where product_type = 'ACCESSORY'
     ) then
    raise exception using
      errcode = '23514',
      message = 'Non-content catalog count/checksum verifier failed.';
  end if;
end;
$verify$;

commit;

